using ClipBridge;
using System.Reflection;
using System.Text.Json;
static class ProviderInvitation
{
 public static void Run(string directory){var connection=JsonSerializer.Deserialize<GroupConnection>(Console.In.ReadToEnd(),Wire.Json)!;Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);Application.EnableVisualStyles();GroupIdentity a=GroupIdentity.Create(Guid.NewGuid().ToString("N"),"Windows owner"),b=GroupIdentity.Create(Guid.NewGuid().ToString("N"),"Phone member");var group=Groups.Create(a,"Invitation check",connection);var locations=new List<string>();void CleanupRecord()=>File.WriteAllText(Path.Combine(directory,"cleanup.json"),JsonSerializer.Serialize(new{group=group.Id,invitations=locations},Wire.Json));CleanupRecord();Exception? error=null;using var pump=new Form{ShowInTaskbar=false,Opacity=0};pump.Shown+=async(_,_)=>{try{
 using(var store=new GroupStore(group))await store.Publish(a,CancellationToken.None);using(var host=await GroupSession.Invite(group,a,()=>{},CancellationToken.None)){locations.Add(host.Code[..6]);CleanupRecord();using var guest=await GroupSession.Join(connection,host.Code,b,_=>{},CancellationToken.None);for(int i=0;i<40&&!host.Done;i++){await host.Step(CancellationToken.None);await guest.Step(CancellationToken.None);if(host.Ready&&!host.Approved)host.Approve();if(guest.Ready&&!guest.Approved)guest.Approve();}if(!host.Done||!guest.Done)throw new Exception("Initial pairing incomplete");}
 group=JsonSerializer.Deserialize<DeviceGroup>(JsonSerializer.Serialize(group,Wire.Json),Wire.Json)!;var type=Assembly.Load("ClipBridge.Windows").GetType("GroupWizard")!;Func<string,GroupConnection,string,CancellationToken,Task<DeviceGroup>> create=(_,_,_,_)=>throw new Exception("Existing group must not be recreated");
 for(int attempt=0;attempt<2;attempt++){using var dialog=(Form)Activator.CreateInstance(type,[a,false,group,create,(Action)(()=>{}),(Action<DeviceGroup>)(_=>{}),(Action<string>)(_=>{})])!;dialog.Shown+=async(_,_)=>{try{await (Task)type.GetMethod("Begin",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(dialog,null)!;var session=(GroupSession?)type.GetField("session",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(dialog);if(session is null)throw new Exception("Existing group invite failed: "+((Label)type.GetField("feedback",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(dialog)!).Text);locations.Add(session.Code[..6]);CleanupRecord();Console.WriteLine("PASS persisted Windows WebDAV group generates another real invitation");}catch(Exception e){error=e;}finally{dialog.Close();}};dialog.ShowDialog(pump);if(error is not null)throw error;}
 }catch(Exception e){error=e;}finally{pump.Close();}};Application.Run(pump);if(error is not null)throw error;}
}
